2	
3	import com.cc91.userservice.security.JwtAuthenticationFilter;
4	import com.cc91.userservice.security.UserDetailsServiceImpl;
5	import org.springframework.beans.factory.annotation.Value;
6	import org.springframework.context.annotation.Bean;
7	import org.springframework.context.annotation.Configuration;
8	import org.springframework.http.HttpStatus;
9	import org.springframework.security.authentication.AuthenticationManager;
10	import org.springframework.security.authentication.dao.DaoAuthenticationProvider;
11	import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
12	import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
13	import org.springframework.security.config.annotation.web.builders.HttpSecurity;
14	import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
15	import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;
16	import org.springframework.security.config.http.SessionCreationPolicy;
17	import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
18	import org.springframework.security.crypto.password.PasswordEncoder;
19	import org.springframework.security.web.SecurityFilterChain;
20	import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
21	import org.springframework.web.cors.CorsConfiguration;
22	import org.springframework.web.cors.CorsConfigurationSource;
23	import org.springframework.web.cors.UrlBasedCorsConfigurationSource;
24	
25	import java.util.Arrays;
26	import java.util.List;
27	
28	@Configuration
29	@EnableWebSecurity
30	@EnableMethodSecurity
31	public class SecurityConfig {
32	
33	    private final UserDetailsServiceImpl userDetailsService;
34	    private final JwtAuthenticationFilter jwtAuthenticationFilter;
35	
36	    @Value("${cors.allowed-origins}")
37	    private String allowedOrigins;
38	
39	    @Value("${cors.allowed-methods}")
40	    private String allowedMethods;
41	
42	    public SecurityConfig(UserDetailsServiceImpl userDetailsService, JwtAuthenticationFilter jwtAuthenticationFilter) {
43	        this.userDetailsService = userDetailsService;
44	        this.jwtAuthenticationFilter = jwtAuthenticationFilter;
45	    }
46	
47	    @Bean
48	    public PasswordEncoder passwordEncoder() {
49	        return new BCryptPasswordEncoder();
50	    }
51	
52	    @Bean
53	    public DaoAuthenticationProvider authenticationProvider() {
54	        DaoAuthenticationProvider authProvider = new DaoAuthenticationProvider();
55	        authProvider.setUserDetailsService(userDetailsService);
56	        authProvider.setPasswordEncoder(passwordEncoder());
57	        return authProvider;
58	    }
59	
60	    @Bean
61	    public AuthenticationManager authenticationManager(AuthenticationConfiguration authConfig) throws Exception {
62	        return authConfig.getAuthenticationManager();
63	    }
64	
65	    @Bean
66	    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
67	        http
68	                .csrf(AbstractHttpConfigurer::disable)
69	                .cors(cors -> cors.configurationSource(corsConfigurationSource()))
70	                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
71	                .exceptionHandling(exceptions -> exceptions
72	                        .authenticationEntryPoint((request, response, authException) -> {
73	                            response.setStatus(HttpStatus.UNAUTHORIZED.value());
74	                            response.setContentType("application/json;charset=UTF-8");
75	                            response.getWriter().write("{\"message\":\"Authentication required\"}");
76	                        })
77	                        .accessDeniedHandler((request, response, accessDeniedException) -> {
78	                            response.setStatus(HttpStatus.FORBIDDEN.value());
79	                            response.setContentType("application/json;charset=UTF-8");
80	                            response.getWriter().write("{\"message\":\"Access denied\"}");
81	                        })
82	                )
83	                .authorizeHttpRequests(auth -> auth
84	                        // All auth endpoints are public for registration, verification,
85	                        // login, token refresh, and password reset flows.
86	                        .requestMatchers("/api/auth/**").permitAll()
87	                        // Public user profile viewing
88	                        .requestMatchers("GET", "/api/users/{username}").permitAll()
89	                        // All other user endpoints require authentication
90	                        .anyRequest().authenticated()
91	                )
92	                .authenticationProvider(authenticationProvider())
93	                .addFilterBefore(jwtAuthenticationFilter, UsernamePasswordAuthenticationFilter.class);
94	
95	        return http.build();
96	    }
97	
98	    @Bean
99	    public CorsConfigurationSource corsConfigurationSource() {
100	        CorsConfiguration configuration = new CorsConfiguration();
101	        List<String> origins = Arrays.asList(allowedOrigins.split(","));
102	        configuration.setAllowedOrigins(origins);
103	        configuration.setAllowedMethods(Arrays.asList(allowedMethods.split(",")));
104	        configuration.setAllowedHeaders(Arrays.asList("*"));
105	        configuration.setAllowCredentials(true);
106	        configuration.setMaxAge(3600L);
107	
108	        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
109	        source.registerCorsConfiguration("/**", configuration);
110	        return source;
111	    }
112	}
