1	package com.cc91.forumservice.service;
2	
3	import com.cc91.forumservice.client.CreateNotificationRequest;
4	import com.cc91.forumservice.client.NotificationServiceClient;
5	import com.cc91.forumservice.client.UserInfoDTO;
6	import com.cc91.forumservice.client.UserServiceClient;
7	import com.cc91.forumservice.dto.CommentResponse;
8	import com.cc91.forumservice.dto.CreateCommentRequest;
9	import com.cc91.forumservice.dto.UserCommentResponse;
10	import com.cc91.forumservice.entity.Comment;
11	import com.cc91.forumservice.entity.Post;
12	import com.cc91.forumservice.exception.ResourceNotFoundException;
13	import com.cc91.forumservice.util.HtmlSanitizer;
14	import com.cc91.forumservice.exception.UnauthorizedException;
15	import com.cc91.forumservice.repository.CommentRepository;
16	import com.cc91.forumservice.repository.PostRepository;
17	import org.slf4j.Logger;
18	import org.slf4j.LoggerFactory;
19	import org.springframework.stereotype.Service;
20	import org.springframework.transaction.annotation.Transactional;
21	
22	import java.util.*;
23	import java.util.stream.Collectors;
24	
25	/**
26	 * 评论服务
27	 */
28	@Service
29	public class CommentService {
30	
31	    private static final Logger logger = LoggerFactory.getLogger(CommentService.class);
32	
33	    private final CommentRepository commentRepository;
34	    private final PostRepository postRepository;
35	    private final UserServiceClient userServiceClient;
36	    private final NotificationServiceClient notificationServiceClient;
37	
38	    public CommentService(CommentRepository commentRepository,
39	                         PostRepository postRepository,
40	                         UserServiceClient userServiceClient,
41	                         NotificationServiceClient notificationServiceClient) {
42	        this.commentRepository = commentRepository;
43	        this.postRepository = postRepository;
44	        this.userServiceClient = userServiceClient;
45	        this.notificationServiceClient = notificationServiceClient;
46	    }
47	
48	    /**
49	     * 创建评论
50	     */
51	    @Transactional
52	    public CommentResponse createComment(String username, Long postId, CreateCommentRequest request) {
53	        UserInfoDTO user = userServiceClient.getUserByUsername(username);
54	        if (user == null) {
55	            throw new ResourceNotFoundException("用户不存在");
56	        }
57	
58	        Post post = postRepository.findById(postId)
59	                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));
60	
61	        Comment comment = new Comment(postId, user.getId(), HtmlSanitizer.sanitizeContent(request.getContent()), null);
62	        comment = commentRepository.save(comment);
63	
64	        // 如果评论的不是自己的帖子，通知帖子作者
65	        if (!post.getAuthorId().equals(user.getId())) {
66	            try {
67	                UserInfoDTO postAuthor = userServiceClient.getUserById(post.getAuthorId());
68	                if (postAuthor != null) {
69	                    notificationServiceClient.createNotification(
70	                            new CreateNotificationRequest(
71	                                    post.getAuthorId(),
72	                                    "REPLY",
73	                                    "新评论通知",
74	                                    user.getUsername() + " 评论了你的帖子: " + post.getTitle(),
75	                                    comment.getId()
76	                            )
77	                    );
78	                }
79	            } catch (Exception e) {
80	                logger.warn("Failed to send notification for comment on post {}", postId, e);
81	            }
82	        }
83	
84	        logger.info("评论创建成功: id={}, postId={}, author={}", comment.getId(), postId, username);
85	
86	        return toCommentResponse(comment, user.getUsername(), user.getAvatarUrl());
87	    }
88	
89	    /**
90	     * 回复评论
91	     */
92	    @Transactional
93	    public CommentResponse replyToComment(String username, Long commentId, CreateCommentRequest request) {
94	        UserInfoDTO user = userServiceClient.getUserByUsername(username);
95	        if (user == null) {
96	            throw new ResourceNotFoundException("用户不存在");
97	        }
98	
99	        Comment parentComment = commentRepository.findById(commentId)
100	                .orElseThrow(() -> new ResourceNotFoundException("评论不存在"));
101	
102	        Comment reply = new Comment(parentComment.getPostId(), user.getId(),
103	                                    HtmlSanitizer.sanitizeContent(request.getContent()), commentId);
104	        reply = commentRepository.save(reply);
105	
106	        // 通知被回复的评论作者（如果不是自己回复自己）
107	        if (!parentComment.getAuthorId().equals(user.getId())) {
108	            try {
109	                Post post = postRepository.findById(parentComment.getPostId()).orElse(null);
110	                String postTitle = post != null ? post.getTitle() : "未知帖子";
111	                notificationServiceClient.createNotification(
112	                        new CreateNotificationRequest(
113	                                parentComment.getAuthorId(),
114	                                "REPLY",
115	                                "新回复通知",
116	                                user.getUsername() + " 回复了你在「" + postTitle + "」中的评论",
117	                                reply.getId()
118	                        )
119	                );
120	            } catch (Exception e) {
121	                logger.warn("Failed to send notification for reply to comment {}", commentId, e);
122	            }
123	        }
124	
125	        logger.info("回复评论成功: id={}, parentId={}, author={}", reply.getId(), commentId, username);
126	
127	        return toCommentResponse(reply, user.getUsername(), user.getAvatarUrl());
128	    }
129	
130	    /**
131	     * 编辑评论
132	     */
133	    @Transactional
134	    public CommentResponse updateComment(String username, Long commentId, String content) {
135	        UserInfoDTO user = userServiceClient.getUserByUsername(username);
136	        if (user == null) {
137	            throw new ResourceNotFoundException("用户不存在");
138	        }
139	
140	        Comment comment = commentRepository.findById(commentId)
141	                .orElseThrow(() -> new ResourceNotFoundException("评论不存在"));
142	
143	        if (!comment.getAuthorId().equals(user.getId())) {
144	            throw new UnauthorizedException("无权限编辑此评论");
145	        }
146	
147	        comment.setContent(HtmlSanitizer.sanitizeContent(content));
148	        comment = commentRepository.save(comment);
149	
150	        logger.info("评论更新成功: id={}, author={}", commentId, username);
151	
152	        return toCommentResponse(comment, user.getUsername(), user.getAvatarUrl());
153	    }
154	
155	    /**
156	     * 删除评论（软删除）
157	     */
158	    @Transactional
159	    public void deleteComment(String username, Long commentId) {
160	        UserInfoDTO user = userServiceClient.getUserByUsername(username);
161	        if (user == null) {
162	            throw new ResourceNotFoundException("用户不存在");
163	        }
164	
165	        Comment comment = commentRepository.findById(commentId)
166	                .orElseThrow(() -> new ResourceNotFoundException("评论不存在"));
167	
168	        if (!comment.getAuthorId().equals(user.getId())) {
169	            throw new UnauthorizedException("无权限删除此评论");
170	        }
171	
172	        comment.setStatus("DELETED");
173	        commentRepository.save(comment);
174	
175	        List<Comment> replies = commentRepository.findByParentIdOrderByCreatedAtAsc(commentId);
176	        for (Comment reply : replies) {
177	            reply.setStatus("DELETED");
178	        }
179	        commentRepository.saveAll(replies);
180	
181	        logger.info("评论删除成功: id={}, 关联子评论数={}, author={}", commentId, replies.size(), username);
182	    }
183	
184	    /**
185	     * 获取帖子的所有评论（树形结构）
186	     */
187	    @Transactional(readOnly = true)
188	    public List<CommentResponse> getCommentsByPostId(Long postId) {
189	        Post post = postRepository.findById(postId)
190	                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));
191	
192	        List<Comment> comments = commentRepository.findByPostIdAndStatusOrderByCreatedAtAsc(postId, "PUBLISHED");
193	
194	        Set<Long> authorIds = comments.stream()
195	                .map(Comment::getAuthorId)
196	                .collect(Collectors.toSet());
197	
198	        Map<Long, UserInfoDTO> userMap = new HashMap<>();
199	        for (Long authorId : authorIds) {
200	            UserInfoDTO user = userServiceClient.getUserById(authorId);
201	            if (user != null) {
202	                userMap.put(authorId, user);
203	            }
204	        }
205	
206	        return buildCommentTree(comments, userMap);
207	    }
208	
209	    /**
210	     * 获取当前用户的评论列表（用于 Dashboard "我的评论"）
211	     */
212	    @Transactional(readOnly = true)
213	    public List<UserCommentResponse> getMyComments(String username) {
214	        UserInfoDTO user = userServiceClient.getUserByUsername(username);
215	        if (user == null) {
216	            throw new ResourceNotFoundException("用户不存在");
217	        }
218	
219	        List<Comment> comments = commentRepository.findByAuthorIdAndStatusOrderByCreatedAtDesc(user.getId(), "PUBLISHED");
220	        if (comments.isEmpty()) {
221	            return Collections.emptyList();
222	        }
223	
224	        Set<Long> postIds = comments.stream()
225	                .map(Comment::getPostId)
226	                .collect(Collectors.toSet());
227	
228	        Map<Long, String> postTitleMap = postRepository.findAllById(postIds).stream()
229	                .collect(Collectors.toMap(Post::getId, Post::getTitle));
230	
231	        return comments.stream()
232	                .map(c -> new UserCommentResponse(
233	                        c.getId(),
234	                        c.getPostId(),
235	                        postTitleMap.getOrDefault(c.getPostId(), "未知帖子"),
236	                        c.getContent(),
237	                        c.getParentId(),
238	                        c.getCreatedAt(),
239	                        c.getStatus()
240	                ))
241	                .collect(Collectors.toList());
242	    }
243	
244	    /**
245	     * 构建评论树形结构
246	     */
247	    private List<CommentResponse> buildCommentTree(List<Comment> comments, Map<Long, UserInfoDTO> userMap) {
248	        List<CommentResponse> responses = comments.stream()
249	                .map(comment -> {
250	                    UserInfoDTO user = userMap.get(comment.getAuthorId());
251	                    String username = user != null ? user.getUsername() : "未知用户";
252	                    String avatarUrl = user != null ? user.getAvatarUrl() : null;
253	                    CommentResponse response = toCommentResponse(comment, username, avatarUrl);
254	                    response.setAuthorAvatarUrl(normalizeAvatarUrl(avatarUrl));
255	                    return response;
256	                })
257	                .collect(Collectors.toList());
258	
259	        Map<Long, CommentResponse> responseMap = new HashMap<>();
260	        for (CommentResponse response : responses) {
261	            responseMap.put(response.getId(), response);
262	        }
263	
264	        List<CommentResponse> rootComments = new ArrayList<>();
265	        for (CommentResponse response : responses) {
266	            if (response.getParentId() == null) {
267	                rootComments.add(response);
268	            } else {
269	                CommentResponse parent = responseMap.get(response.getParentId());
270	                if (parent != null) {
271	                    parent.getReplies().add(response);
272	                }
273	            }
274	        }
275	
276	        return rootComments;
277	    }
