315	    @Transactional
316	    public void resetPassword(String email, String code, String newPassword) {
317	        VerificationCode verificationCode = verificationCodeRepository
318	                .findByEmailAndCode(email, code)
319	                .orElseThrow(() -> new BadRequestException(VERIFICATION_CODE_NOT_FOUND));
320	
321	        validateVerificationCode(verificationCode);
322	        if (!PASSWORD_RESET_CODE_TYPE.equals(verificationCode.getType())) {
323	            throw new BadRequestException(VERIFICATION_CODE_TYPE_INVALID);
324	        }
325	
326	        User user = userRepository.findByEmail(email)
327	                .orElseThrow(() -> new ResourceNotFoundException(USER_NOT_FOUND));
328	
329	        user.setPasswordHash(passwordEncoder.encode(newPassword));
330	        user.setFailedLoginAttempts(0);
331	        user.setIsLocked(false);
332	        user.setLockUntil(null);
333	        userRepository.save(user);
334	
335	        verificationCode.setUsed(true);
336	        verificationCodeRepository.save(verificationCode);
337	
338	        revokeAllUserTokens(user.getId());
339	        logger.info("Password reset completed: {}", email);
340	    }
