342	    private void validateVerificationCode(VerificationCode verificationCode) {
343	        if (verificationCode.getUsed()) {
344	            throw new BadRequestException(VERIFICATION_CODE_USED);
345	        }
346	        if (verificationCode.isExpired()) {
347	            throw new BadRequestException(VERIFICATION_CODE_EXPIRED);
348	        }
349	    }
