35	    /**
36	     * 创建举报
37	     *
38	     * @param username    举报人用户名
39	     * @param targetId    被举报目标 ID
40	     * @param targetType  目标类型 (POST / COMMENT)
41	     * @param reason      举报原因
42	     * @param description 补充描述（拼接到 reason 中）
43	     * @return 保存后的 Report 实体
44	     */
45	    @Transactional
46	    public Report createReport(String username, Long targetId, String targetType, String reason, String description) {
