56	        }
57	
58	        Report report = new Report(user.getId(), type, targetId, fullReason);
59	        report = reportRepository.save(report);
60	
61	        logger.info("举报创建成功: id={}, reporter={}, targetType={}, targetId={}",
62	                report.getId(), username, targetType, targetId);
63	
64	        return report;
