78	
79	        if (status == null || status.trim().isEmpty()) {
80	            return reportRepository.findAllByOrderByCreatedAtDesc(pageable);
81	        }
82	
83	        Report.ReportStatus reportStatus = Report.ReportStatus.valueOf(status.toUpperCase());
84	        return reportRepository.findByStatusOrderByCreatedAtDesc(reportStatus, pageable);
