@RestController
@RequestMapping("/api/upload")
public class FileUploadController {
    private static final long MAX_IMAGE_SIZE = 2 * 1024 * 1024;
    private static final List<String> ALLOWED_TYPES = List.of("image/jpeg", "image/png", "image/gif", "image/webp");
    private final UserServiceClient userServiceClient;

    @PostMapping("/avatar")
    public ResponseEntity<ApiResponse<Map<String, String>>> uploadAvatar(@RequestParam("file") MultipartFile file) {
        String username = getCurrentUsername();
        // Validate file
        validateFile(file);
        // Store file
        String filename = UUID.randomUUID() + getExtension(file);
        Path uploadDir = Path.of("uploads/avatars");
        Files.createDirectories(uploadDir);
        file.transferTo(uploadDir.resolve(filename).toFile());
        String avatarUrl = "/uploads/avatars/" + filename;
        // Update user profile via Feign
        UserInfoDTO user = userServiceClient.getUserByUsername(username);
        userServiceClient.updateAvatar(user.getId(), new UpdateAvatarRequest(avatarUrl));
        return ResponseEntity.ok(ApiResponse.success("头像上传成功", Map.of("avatarUrl", avatarUrl)));
    }

    @PostMapping("/images")
    public ResponseEntity<ApiResponse<Map<String, String>>> uploadImage(@RequestParam("file") MultipartFile file) {
        getCurrentUsername();
        validateFile(file);
        String filename = UUID.randomUUID() + getExtension(file);
        Path uploadDir = Path.of("uploads/images");
        Files.createDirectories(uploadDir);
        file.transferTo(uploadDir.resolve(filename).toFile());
        String url = "/uploads/images/" + filename;
        return ResponseEntity.ok(ApiResponse.success("上传成功", Map.of("url", url)));
    }
}
